		/** Builds a string from a printf-style format. */
		static FString Printf(const wchar_t* Fmt, ...)
		{
			if (!Fmt)
			{
				return FString();
			}

			int32 BufferSize = 512;
			for (;;)
			{
				std::vector<wchar_t> Buffer(static_cast<size_t>(BufferSize));

				va_list Args;
				va_start(Args, Fmt);
				const int Written = _vsnwprintf_s(Buffer.data(), Buffer.size(), _TRUNCATE, Fmt, Args);
				va_end(Args);

				if (Written >= 0)
				{
					return FString(Buffer.data());
				}

				BufferSize *= 2;
				if (BufferSize > (1 << 20))
				{
					return FString();
				}
			}
		}

